package org.chromium.url;import java.net.URI;public class GURL { private URI uri;public GURL(String s){try{uri=URI.create(s);}catch(Exception e){}} public boolean isValid(){return uri!=null&&uri.getHost()!=null;}public String getScheme(){return uri.getScheme();}public String getSpec(){return uri.toString();}public GURL getOrigin(){return new GURL(getScheme()+"://"+uri.getHost()+(uri.getPort()<0?"":":"+uri.getPort())+"/");} }
